SELECT id, product_name, cost, launch_date, supplier_id, CUME_DIST() OVER (ORDER BY stock_qty NULLS FIRST) AS stock_qty_cume_dist, CORR(stock_qty, price) OVER w_hist AS corr_stock_qty_price, ROUND(cost / SUM(cost) OVER (PARTITION BY supplier_id, brand), 4) AS cost_share, CUME_DIST() OVER (ORDER BY stock_qty DESC) AS stock_qty_cume_dist_2 FROM products WINDOW w_hist AS (PARTITION BY supplier_id);
